"""Absence notices for parents."""

from typing import Iterable

from rosterkit.models import Mark, Student
from rosterkit.errors import ProjectError

# ---
def build_notice(
    student: Student, marks: Iterable[Mark]
) -> str:
    """Short text naming the student and the absent days."""
    marks = list(marks)
    for mark in marks:
        if mark.student_id != student.student_id:
            raise ProjectError(
                f"mark for {mark.student_id} given for "
                f"{student.student_id}"
            )
    days = sorted(
        mark.day
        for mark in marks
        if mark.status == "absent"
    )
    if not days:
        raise ProjectError("no absences to report")
    name = f"{student.first_name} {student.last_name}"
    count = len(days)
    noun = "day" if count == 1 else "days"
    listed = ", ".join(item.isoformat() for item in days)
    return (
        f"{name} was absent for {count} {noun}: {listed}."
    )

