import unittest
from datetime import date

from rosterkit.notices import build_notice
from rosterkit.models import Mark, Student
from rosterkit.errors import ProjectError

PUPIL = Student("7", "Lovelace", "Ada", "A")

def mark(day, status="absent", who="7"):
    return Mark(who, day, status)

class NoticeTests(unittest.TestCase):
    def test_lists_absent_days_in_order(self):
        text = build_notice(PUPIL, [
            mark(date(2026, 9, 5)),
            mark(date(2026, 9, 4), "present"),
            mark(date(2026, 9, 2))
        ])
        self.assertEqual(
            text,
            "Ada Lovelace was absent for 2 days: "
            "2026-09-02, 2026-09-05."
        )

    def test_single_day(self):
        text = build_notice(PUPIL, [mark(date(2026, 9, 2))])
        self.assertIn("1 day:", text)

    def test_other_student(self):
        with self.assertRaises(ProjectError):
            build_notice(PUPIL, [
                mark(date(2026, 9, 2)),
                mark(date(2026, 9, 3), who="8")
            ])

    def test_no_absences(self):
        with self.assertRaises(ProjectError):
            build_notice(PUPIL, [
                mark(date(2026, 9, 2), "late")
            ])

if __name__ == "__main__":
    unittest.main()
